import React, { useState, useEffect } from 'react';
import { Elements } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';
import PaymentModal from '../components/PaymentModal';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import DiscoveryPage from './DiscoveryPage';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY);

function CustomerDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [services, setServices] = useState([]);
  const [vehicles, setVehicles] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [paymentHistory, setPaymentHistory] = useState([]);
  const [onlineDrivers, setOnlineDrivers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingPayments, setLoadingPayments] = useState(false);
  const [showBookingModal, setShowBookingModal] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [selectedService, setSelectedService] = useState(null);
  const [pendingBooking, setPendingBooking] = useState(null);
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(3);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showDiscovery, setShowDiscovery] = useState(false);

  // REFUND STATES
  const [refundRequests, setRefundRequests] = useState([]);
  const [showRefundModal, setShowRefundModal] = useState(false);
  const [selectedBookingForRefund, setSelectedBookingForRefund] = useState(null);
  const [refundReason, setRefundReason] = useState('');
  const [loadingRefund, setLoadingRefund] = useState(false);

  const [bookingData, setBookingData] = useState({
    date: '', time: '', vehicleId: '', isConcierge: false, pickupAddress: '', notes: ''
  });

  const [profile, setProfile] = useState({
    fullName: `${user?.firstName || ''} ${user?.lastName || ''}`,
    email: user?.email || '',
    phone: user?.phone || '',
    avatar: user?.profilePicture || 'https://ui-avatars.com/api/?background=2563eb&color=fff&name=' + encodeURIComponent(user?.firstName || 'User'),
    preferredLocation: user?.address || '',
    loyaltyPoints: 1250,
    memberSince: new Date(user?.createdAt || Date.now()).toLocaleDateString()
  });

  const [settings, setSettings] = useState({
    emailNotifications: true, pushNotifications: true, smsNotifications: false,
    darkMode: false, language: 'english', hideProfile: false, offlineMode: false
  });

  const [newVehicle, setNewVehicle] = useState({ make: '', model: '', year: '', licensePlate: '', color: '' });
  const [filters, setFilters] = useState({ category: 'all', search: '', minPrice: '', maxPrice: '' });
  const [selectedDate, setSelectedDate] = useState(new Date());

  const token = localStorage.getItem('token');

  const sampleNotifications = [
    { id: 1, type: 'booking_confirmed', title: 'Booking Confirmed', message: 'Your service has been confirmed', time: '2 hours ago', read: false, icon: '✅' },
    { id: 2, type: 'driver_assigned', title: 'Driver Assigned', message: 'A driver has been assigned', time: '5 hours ago', read: false, icon: '🚗' }
  ];

  useEffect(() => {
    fetchAllData();
    fetchPaymentHistory();
    fetchRefundRequests();
    setNotifications(sampleNotifications);
    const interval = setInterval(fetchOnlineDrivers, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([fetchServices(), fetchVehicles(), fetchBookings(), fetchOnlineDrivers()]);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const fetchServices = async () => {
    try {
      let url = 'http://localhost:5000/api/services?';
      if (filters.category && filters.category !== 'all') url += `category=${filters.category}&`;
      if (filters.search) url += `search=${filters.search}&`;
      if (filters.minPrice) url += `minPrice=${filters.minPrice}&`;
      if (filters.maxPrice) url += `maxPrice=${filters.maxPrice}&`;
      const res = await fetch(url);
      const data = await res.json();
      if (data.success) setServices(data.services);
    } catch (error) { console.error('Error fetching services:', error); }
  };

  const fetchVehicles = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/services/customer/vehicles', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) setVehicles(data.vehicles);
    } catch (error) { console.error('Error fetching vehicles:', error); }
  };

  const fetchBookings = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/services/customer/bookings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) setBookings(data.bookings);
    } catch (error) { console.error('Error fetching bookings:', error); }
  };

  const fetchOnlineDrivers = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/driver/online');
      const data = await res.json();
      if (data.success) setOnlineDrivers(data.drivers || []);
    } catch (error) { console.error('Error fetching drivers:', error); }
  };

  const fetchPaymentHistory = async () => {
    setLoadingPayments(true);
    try {
      const res = await fetch('http://localhost:5000/api/payments/customer/history', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) setPaymentHistory(data.payments);
    } catch (error) {
      console.error('Error fetching payment history:', error);
    } finally {
      setLoadingPayments(false);
    }
  };

  const fetchRefundRequests = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/refunds/my-refunds', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) setRefundRequests(data.refunds);
    } catch (error) {
      console.error('Error fetching refund requests:', error);
    }
  };

  const requestRefund = async () => {
    if (!refundReason.trim()) {
      toast.error('Please provide a reason for refund');
      return;
    }

    setLoadingRefund(true);
    try {
      const res = await fetch('http://localhost:5000/api/refunds/request', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          bookingId: selectedBookingForRefund._id,
          reason: refundReason
        })
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Refund request submitted! Admin will review.');
        setShowRefundModal(false);
        setSelectedBookingForRefund(null);
        setRefundReason('');
        fetchRefundRequests();
        fetchBookings();
      } else {
        toast.error(data.error || 'Failed to request refund');
      }
    } catch (error) {
      toast.error('Failed to request refund');
    } finally {
      setLoadingRefund(false);
    }
  };

  const createBooking = async () => {
    if (!bookingData.date) { toast.error('Please select a date'); return; }
    if (!bookingData.time) { toast.error('Please select a time'); return; }
    if (vehicles.length === 0 && !bookingData.vehicleId) {
      toast.error('Please add a vehicle first');
      setShowVehicleModal(true);
      return;
    }
    const vehicleId = bookingData.vehicleId || (vehicles[0]?._id);
    if (!vehicleId) { toast.error('Please select a vehicle'); return; }

    try {
      const payload = {
        serviceId: selectedService._id, vehicleId, bookingDate: bookingData.date,
        bookingTime: bookingData.time, isConcierge: bookingData.isConcierge,
        pickupAddress: bookingData.pickupAddress, notes: bookingData.notes
      };
      const res = await fetch('http://localhost:5000/api/services/customer/bookings', {
        method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (data.success) {
        setPendingBooking(data.booking);
        setShowBookingModal(false);
        setShowPaymentModal(true);
      } else {
        toast.error(data.error || 'Failed to create booking');
      }
    } catch (error) {
      console.error('Error creating booking:', error);
      toast.error('Failed to create booking');
    }
  };

  const addVehicle = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/services/customer/vehicles', {
        method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify(newVehicle)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Vehicle added successfully!');
        setShowVehicleModal(false);
        setNewVehicle({ make: '', model: '', year: '', licensePlate: '', color: '' });
        fetchVehicles();
      }
    } catch (error) { toast.error('Failed to add vehicle'); }
  };

  const updateProfile = async (e) => { e.preventDefault(); toast.success('Profile updated!'); setShowProfileModal(false); };
  const updateSettings = async (e) => { e.preventDefault(); setDarkMode(settings.darkMode); toast.success('Settings saved!'); setShowSettingsModal(false); };

  const getStatusBadge = (status) => {
    const colors = { pending: '#f59e0b', confirmed: '#10b981', 'in-progress': '#3b82f6', completed: '#8b5cf6', cancelled: '#ef4444' };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  const totalSpent = bookings.filter(b => b.status === 'completed').reduce((sum, b) => sum + (b.totalAmount || 0), 0);
  const upcomingBookings = bookings.filter(b => b.status !== 'completed' && b.status !== 'cancelled');
  const completedBookings = bookings.filter(b => b.status === 'completed');

  if (showDiscovery) {
    return <DiscoveryPage user={user} onBack={() => setShowDiscovery(false)} />;
  }

  return (
    <div style={{ ...styles.dashboard, backgroundColor: darkMode ? '#1a1a2e' : '#f3f4f6' }}>
      <ToastContainer position="top-right" />

      {/* Header */}
      <div style={{ ...styles.header, backgroundColor: darkMode ? '#16213e' : '#1f2937' }}>
        <div style={styles.logoSection}><span style={styles.logoIcon}>🚗💨</span><h1 style={styles.logoText}>Car Care Connect</h1></div>
        <div style={styles.headerRight}>
          <div style={styles.notificationIcon} onClick={() => setShowNotifications(!showNotifications)}>🔔{unreadCount > 0 && <span style={styles.notificationBadge}>{unreadCount}</span>}</div>
          <button style={styles.themeToggle} onClick={() => { setDarkMode(!darkMode); setSettings({...settings, darkMode: !darkMode}); }}>{darkMode ? '☀️' : '🌙'}</button>
          <button style={styles.discoveryBtn} onClick={() => setShowDiscovery(true)}>🔍 Discover</button>
          <div style={styles.userInfo}><img src={profile.avatar} alt="avatar" style={styles.avatar} /><span>{user?.firstName} {user?.lastName}</span><button onClick={onLogout} style={styles.logoutButton}>Logout</button></div>
        </div>
      </div>

      {/* Notification Dropdown */}
      {showNotifications && (
        <div style={{ ...styles.notificationDropdown, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
          <div style={styles.notificationHeader}><h3>Notifications</h3><button onClick={() => { setNotifications(notifications.map(n => ({ ...n, read: true }))); setUnreadCount(0); }} style={styles.markAllRead}>Mark all read</button></div>
          {notifications.map(notif => (
            <div key={notif.id} style={{ ...styles.notificationItem, opacity: notif.read ? 0.6 : 1 }} onClick={() => { setNotifications(notifications.map(n => n.id === notif.id ? { ...n, read: true } : n)); setUnreadCount(Math.max(0, unreadCount - 1)); }}>
              <span style={styles.notificationIconSmall}>{notif.icon}</span>
              <div style={styles.notificationContent}><div style={styles.notificationTitle}>{notif.title}</div><div style={styles.notificationMessage}>{notif.message}</div><div style={styles.notificationTime}>{notif.time}</div></div>
            </div>
          ))}
        </div>
      )}

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        <div style={{ ...styles.statCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h3>🚗 Vehicles</h3><p style={styles.statNumber}>{vehicles.length}</p><button style={styles.smallBtn} onClick={() => setShowVehicleModal(true)}>+ Add</button></div>
        <div style={{ ...styles.statCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h3>📅 Bookings</h3><p style={styles.statNumber}>{bookings.length}</p></div>
        <div style={{ ...styles.statCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h3>💰 Spent</h3><p style={styles.statNumber}>${totalSpent.toLocaleString()}</p></div>
        <div style={{ ...styles.statCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h3>⭐ Loyalty</h3><p style={styles.statNumber}>{profile.loyaltyPoints} pts</p></div>
      </div>

      {/* Tabs */}
      <div style={{ ...styles.tabs, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'services' ? styles.activeTab : {})}} onClick={() => { fetchServices(); setActiveTab('services'); }}>🔧 Services</button>
        <button style={{...styles.tab, ...(activeTab === 'vehicles' ? styles.activeTab : {})}} onClick={() => setActiveTab('vehicles')}>🚗 Vehicles</button>
        <button style={{...styles.tab, ...(activeTab === 'bookings' ? styles.activeTab : {})}} onClick={() => setActiveTab('bookings')}>📅 Bookings</button>
        <button style={{...styles.tab, ...(activeTab === 'payments' ? styles.activeTab : {})}} onClick={() => setActiveTab('payments')}>💳 Payments</button>
        <button style={{...styles.tab, ...(activeTab === 'refunds' ? styles.activeTab : {})}} onClick={() => setActiveTab('refunds')}>🔄 Refunds</button>
        <button style={{...styles.tab, ...(activeTab === 'profile' ? styles.activeTab : {})}} onClick={() => setActiveTab('profile')}>👤 Profile</button>
        <button style={{...styles.tab, ...(activeTab === 'settings' ? styles.activeTab : {})}} onClick={() => setActiveTab('settings')}>⚙️ Settings</button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? <div style={styles.loading}>Loading...</div> : (
          <>
            {/* Dashboard Tab */}
            {activeTab === 'dashboard' && (
              <div>
                <div style={{ ...styles.welcomeCard, backgroundColor: '#2563eb' }}><div><h2>Welcome back, {user?.firstName}! 👋</h2><p>Your next service is just a click away</p></div><span style={styles.loyaltyBadge}>⭐ {profile.loyaltyPoints} points</span></div>
                <div style={styles.twoColumn}>
                  <div><div style={{ ...styles.card, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h3>📅 Upcoming Appointments</h3>{upcomingBookings.length === 0 ? <p>No upcoming appointments</p> : upcomingBookings.map(booking => (<div key={booking._id} style={styles.appointmentItem}><div><strong>{booking.serviceName}</strong></div><div>{new Date(booking.bookingDate).toLocaleDateString()} at {booking.bookingTime}</div><span style={getStatusBadge(booking.status)}>{booking.status}</span></div>))}</div></div>
                  <div><div style={{ ...styles.card, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h3>📆 Calendar</h3><Calendar onChange={setSelectedDate} value={selectedDate} /></div><div style={{ ...styles.card, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h3>💰 Spending Summary</h3><div style={styles.spendingItem}><span>Total Spent:</span><strong>${totalSpent.toLocaleString()}</strong></div><div style={styles.spendingItem}><span>Average per booking:</span><strong>${completedBookings.length > 0 ? (totalSpent / completedBookings.length).toFixed(2) : 0}</strong></div></div></div>
                </div>
              </div>
            )}

            {/* Services Tab */}
            {activeTab === 'services' && (
              <div>
                <div style={styles.filtersBar}>
                  <select style={styles.filterSelect} value={filters.category} onChange={(e) => setFilters({...filters, category: e.target.value})}>
                    <option value="all">All Categories</option><option value="oil-change">Oil Change</option><option value="brake-repair">Brake Repair</option>
                    <option value="tire-service">Tire Service</option><option value="engine-repair">Engine Repair</option><option value="car-wash">Car Wash</option><option value="detailing">Detailing</option>
                  </select>
                  <input style={styles.filterInput} type="text" placeholder="Search services..." value={filters.search} onChange={(e) => setFilters({...filters, search: e.target.value})} />
                  <input style={styles.filterInputSmall} type="number" placeholder="Min $" value={filters.minPrice} onChange={(e) => setFilters({...filters, minPrice: e.target.value})} />
                  <input style={styles.filterInputSmall} type="number" placeholder="Max $" value={filters.maxPrice} onChange={(e) => setFilters({...filters, maxPrice: e.target.value})} />
                  <button style={styles.filterBtn} onClick={fetchServices}>Apply</button>
                </div>
                <div style={styles.servicesGrid}>
                  {services.length === 0 ? <div style={styles.emptyState}>No services available.</div> : services.map(service => (
                    <div key={service._id} style={{ ...styles.serviceCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <h3>{service.name}</h3><p style={styles.providerName}>🔧 {service.providerBusinessName || service.providerName}</p>
                      <p>{service.description?.substring(0, 100)}...</p>
                      <div style={styles.servicePrice}><span style={styles.price}>${service.price}</span><span style={styles.duration}>⏱️ {service.duration} min</span></div>
                      <button style={styles.bookBtn} onClick={() => { setSelectedService(service); setShowBookingModal(true); }}>Book Now →</button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Vehicles Tab */}
            {activeTab === 'vehicles' && (
              <div><button style={styles.addVehicleBtn} onClick={() => setShowVehicleModal(true)}>+ Add Vehicle</button>
              {vehicles.length === 0 ? <div style={styles.emptyState}>No vehicles added.</div> : vehicles.map(vehicle => (<div key={vehicle._id} style={{ ...styles.vehicleCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}><strong>{vehicle.year} {vehicle.make} {vehicle.model}</strong><div>License: {vehicle.licensePlate} | Color: {vehicle.color || 'N/A'}</div></div>))}</div>
            )}

            {/* Bookings Tab WITH INVOICE BUTTON */}
            {activeTab === 'bookings' && (
              <div>
                {bookings.length === 0 ? (
                  <div style={styles.emptyState}>No bookings yet.</div>
                ) : (
                  bookings.map(booking => (
                    <div key={booking._id} style={styles.bookingCard}>
                      <div style={styles.bookingHeader}>
                        <div><h3>{booking.serviceName}</h3><p>Provider: {booking.providerId?.businessName || booking.providerId?.firstName}</p></div>
                        <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                      </div>
                      <div style={styles.bookingDetails}>
                        <span>📅 {new Date(booking.bookingDate).toLocaleDateString()}</span>
                        <span>⏰ {booking.bookingTime}</span>
                        <span>💰 ${booking.totalAmount}</span>
                      </div>
                      {booking.status === 'completed' && (
                        <button 
                          onClick={() => fetch(`http://localhost:5000/api/invoices/download/${booking._id}`, { headers: { "Authorization": `Bearer ${token}` } }).then(res => res.blob()).then(blob => { const url = window.URL.createObjectURL(blob); fetch(`http://localhost:5000/api/invoices/download/${booking._id}`, { headers: { "Authorization": `Bearer ${token}` } }).then(res => res.blob()).then(blob => { const url = window.URL.createObjectURL(blob); window.open(url, "_blank"); }); })}
                          style={{ backgroundColor: '#2563eb', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer', marginTop: '10px' }}
                        >
                          📄 Download Invoice
                        </button>
                      )}
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Payments Tab */}
            {activeTab === 'payments' && (
              <div>
                <h2>💳 Payment History</h2>
                {loadingPayments ? <div style={styles.loading}>Loading...</div> : paymentHistory.length === 0 ? <div style={styles.emptyState}>No payment history yet.</div> : paymentHistory.map(payment => (
                  <div key={payment._id} style={styles.bookingCard}>
                    <div style={styles.bookingHeader}><div><h3>{payment.bookingId?.serviceName}</h3><div>{new Date(payment.createdAt).toLocaleDateString()}</div></div>
                    <span style={{ backgroundColor: payment.paymentStatus === 'completed' ? '#d1fae5' : '#fef3c7', color: payment.paymentStatus === 'completed' ? '#065f46' : '#92400e', padding: '4px 12px', borderRadius: '20px' }}>{payment.paymentStatus === 'completed' ? '✅ Paid' : '⏳ Pending'}</span></div>
                    <div><strong>Amount:</strong> ${payment.amount}</div>
                    {payment.paymentStatus === 'completed' && (
                      <button 
                        onClick={() => fetch(`http://localhost:5000/api/invoices/download/${booking._id}`, { headers: { "Authorization": `Bearer ${token}` } }).then(res => res.blob()).then(blob => { const url = window.URL.createObjectURL(blob); fetch(`http://localhost:5000/api/invoices/download/${booking._id}`, { headers: { "Authorization": `Bearer ${token}` } }).then(res => res.blob()).then(blob => { const url = window.URL.createObjectURL(blob); window.open(url, "_blank"); }); })}
                        style={{ backgroundColor: '#2563eb', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer', marginTop: '10px' }}
                      >
                        📄 Download Invoice
                      </button>
                    )}
                  </div>
                ))}
              </div>
            )}

            {/* Refunds Tab */}
            {activeTab === 'refunds' && (
              <div>
                <h2>🔄 Refund Requests</h2>
                {refundRequests.length === 0 ? (
                  <div style={styles.emptyState}>No refund requests yet.</div>
                ) : (
                  refundRequests.map(refund => (
                    <div key={refund._id} style={styles.bookingCard}>
                      <div style={styles.bookingHeader}>
                        <div><h3>{refund.bookingId?.serviceName}</h3><div style={{ fontSize: '12px', color: '#6b7280' }}>Requested: {new Date(refund.requestedAt).toLocaleDateString()}</div></div>
                        <span style={{
                          backgroundColor: refund.status === 'pending' ? '#fef3c7' : refund.status === 'approved' ? '#d1fae5' : '#fee2e2',
                          color: refund.status === 'pending' ? '#92400e' : refund.status === 'approved' ? '#065f46' : '#991b1b',
                          padding: '4px 12px', borderRadius: '20px', fontSize: '12px'
                        }}>
                          {refund.status === 'pending' ? '⏳ Pending' : refund.status === 'approved' ? '✅ Approved' : '❌ Rejected'}
                        </span>
                      </div>
                      <div style={styles.bookingDetails}><span>💰 Amount: ${refund.amount}</span><span>📝 Reason: {refund.reason}</span></div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Profile Tab */}
            {activeTab === 'profile' && (
              <div style={styles.profileContainer}>
                <div style={styles.profileHeader}><img src={profile.avatar} alt="avatar" style={styles.profileAvatar} /><div><h2>{profile.fullName}</h2><p>Member since {profile.memberSince}</p><button style={styles.editProfileBtn} onClick={() => setShowProfileModal(true)}>✏️ Edit Profile</button></div></div>
                <div style={styles.profileInfo}><div><strong>📧 Email:</strong> {profile.email}</div><div><strong>📞 Phone:</strong> {profile.phone}</div><div><strong>📍 Location:</strong> {profile.preferredLocation || 'Not set'}</div><div><strong>⭐ Loyalty Points:</strong> {profile.loyaltyPoints}</div></div>
              </div>
            )}

            {/* Settings Tab */}
            {activeTab === 'settings' && (
              <div style={styles.settingsContainer}>
                <h2>⚙️ Settings</h2>
                <div style={styles.settingsSection}><h3>🔔 Notification Preferences</h3>
                  <label style={styles.settingItem}><input type="checkbox" checked={settings.emailNotifications} onChange={(e) => setSettings({...settings, emailNotifications: e.target.checked})} /> Email</label>
                  <label style={styles.settingItem}><input type="checkbox" checked={settings.pushNotifications} onChange={(e) => setSettings({...settings, pushNotifications: e.target.checked})} /> Push</label>
                </div>
                <button style={styles.saveSettingsBtn} onClick={() => setShowSettingsModal(true)}>Save</button>
              </div>
            )}
          </>
        )}
      </div>

      {/* Booking Modal */}
      {showBookingModal && selectedService && (
        <div style={styles.modal}><div style={{ ...styles.modalContent, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
          <h2>Book {selectedService.name}</h2>
          <p><strong>Provider:</strong> {selectedService.providerBusinessName || selectedService.providerName}</p>
          <p><strong>Price:</strong> ${selectedService.price}</p>
          <label>Vehicle:</label><select style={styles.input} value={bookingData.vehicleId} onChange={(e) => setBookingData({...bookingData, vehicleId: e.target.value})}><option value="">Select</option>{vehicles.map(v => <option key={v._id} value={v._id}>{v.year} {v.make} {v.model}</option>)}</select>
          <label>Date:</label><input type="date" style={styles.input} value={bookingData.date} onChange={(e) => setBookingData({...bookingData, date: e.target.value})} min={new Date().toISOString().split('T')[0]} />
          <label>Time:</label><input type="time" style={styles.input} value={bookingData.time} onChange={(e) => setBookingData({...bookingData, time: e.target.value})} />
          <label><input type="checkbox" checked={bookingData.isConcierge} onChange={(e) => setBookingData({...bookingData, isConcierge: e.target.checked})} /> 🚗 Concierge (+$20)</label>
          {bookingData.isConcierge && (<><label>Pickup Address:</label><textarea style={styles.textarea} value={bookingData.pickupAddress} onChange={(e) => setBookingData({...bookingData, pickupAddress: e.target.value})} /></>)}
          <button style={styles.submitBtn} onClick={createBooking}>Continue to Payment</button>
          <button style={styles.cancelBtn} onClick={() => { setShowBookingModal(false); setSelectedService(null); }}>Cancel</button>
        </div></div>
      )}

      {/* Payment Modal */}
      {showPaymentModal && pendingBooking && (
        <Elements stripe={stripePromise}>
          <PaymentModal booking={pendingBooking} amount={pendingBooking.totalAmount} onSuccess={() => { setShowPaymentModal(false); toast.success('Booking confirmed!'); fetchBookings(); fetchPaymentHistory(); }} onCancel={() => { setShowPaymentModal(false); toast.info('Booking saved. Pay later.'); fetchBookings(); }} />
        </Elements>
      )}

      {/* Refund Modal */}
      {showRefundModal && selectedBookingForRefund && (
        <div style={styles.modal}><div style={{ ...styles.modalContent, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
          <h2>Request Refund</h2>
          <p><strong>Service:</strong> {selectedBookingForRefund.serviceName}</p>
          <p><strong>Amount:</strong> ${selectedBookingForRefund.totalAmount}</p>
          <p><strong>Booking Date:</strong> {new Date(selectedBookingForRefund.bookingDate).toLocaleDateString()}</p>
          <label>Reason for Refund *</label>
          <textarea style={styles.textarea} placeholder="Please explain why you are requesting a refund..." value={refundReason} onChange={(e) => setRefundReason(e.target.value)} rows="4" />
          <div style={styles.modalActions}>
            <button style={styles.submitBtn} onClick={requestRefund} disabled={loadingRefund}>{loadingRefund ? 'Submitting...' : 'Submit Refund Request'}</button>
            <button style={styles.cancelBtn} onClick={() => { setShowRefundModal(false); setSelectedBookingForRefund(null); setRefundReason(''); }}>Cancel</button>
          </div>
        </div></div>
      )}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <div style={styles.modal}><div style={{ ...styles.modalContentSmall, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h2>Add Vehicle</h2><form onSubmit={addVehicle}><input style={styles.input} placeholder="Make" value={newVehicle.make} onChange={(e) => setNewVehicle({...newVehicle, make: e.target.value})} required /><input style={styles.input} placeholder="Model" value={newVehicle.model} onChange={(e) => setNewVehicle({...newVehicle, model: e.target.value})} required /><input style={styles.input} type="number" placeholder="Year" value={newVehicle.year} onChange={(e) => setNewVehicle({...newVehicle, year: e.target.value})} required /><input style={styles.input} placeholder="License Plate" value={newVehicle.licensePlate} onChange={(e) => setNewVehicle({...newVehicle, licensePlate: e.target.value})} required /><input style={styles.input} placeholder="Color" value={newVehicle.color} onChange={(e) => setNewVehicle({...newVehicle, color: e.target.value})} /><div style={styles.modalActions}><button type="submit" style={styles.submitBtn}>Save</button><button type="button" style={styles.cancelBtn} onClick={() => setShowVehicleModal(false)}>Cancel</button></div></form></div></div>
      )}

      {/* Profile Modal */}
      {showProfileModal && (
        <div style={styles.modal}><div style={{ ...styles.modalContent, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h2>Edit Profile</h2><form onSubmit={updateProfile}><input style={styles.input} type="text" placeholder="Full Name" value={profile.fullName} onChange={(e) => setProfile({...profile, fullName: e.target.value})} /><input style={styles.input} type="email" placeholder="Email" value={profile.email} onChange={(e) => setProfile({...profile, email: e.target.value})} /><input style={styles.input} type="tel" placeholder="Phone" value={profile.phone} onChange={(e) => setProfile({...profile, phone: e.target.value})} /><div style={styles.modalActions}><button type="submit" style={styles.submitBtn}>Save</button><button type="button" style={styles.cancelBtn} onClick={() => setShowProfileModal(false)}>Cancel</button></div></form></div></div>
      )}

      {/* Settings Modal */}
      {showSettingsModal && (
        <div style={styles.modal}><div style={{ ...styles.modalContent, backgroundColor: darkMode ? '#1e293b' : 'white' }}><h2>Save Settings</h2><p>Your settings have been updated.</p><div style={styles.modalActions}><button style={styles.submitBtn} onClick={updateSettings}>Save</button><button style={styles.cancelBtn} onClick={() => setShowSettingsModal(false)}>Cancel</button></div></div></div>
      )}
    </div>
  );
}

const styles = {
  dashboard: { minHeight: '100vh', transition: 'background-color 0.3s' },
  header: { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap' },
  logoSection: { display: 'flex', alignItems: 'center', gap: '10px' }, logoIcon: { fontSize: '28px' }, logoText: { fontSize: '1.5rem', fontWeight: 'bold', color: 'white' },
  headerRight: { display: 'flex', alignItems: 'center', gap: '15px' },
  notificationIcon: { position: 'relative', cursor: 'pointer', fontSize: '24px' }, notificationBadge: { position: 'absolute', top: '-5px', right: '-10px', backgroundColor: '#ef4444', color: 'white', fontSize: '10px', padding: '2px 6px', borderRadius: '10px' },
  themeToggle: { background: 'none', border: 'none', fontSize: '20px', cursor: 'pointer', padding: '5px 10px', borderRadius: '20px', backgroundColor: 'rgba(255,255,255,0.2)' },
  discoveryBtn: { background: 'none', border: '1px solid white', color: 'white', padding: '5px 12px', borderRadius: '20px', cursor: 'pointer', fontSize: '14px' },
  avatar: { width: '35px', height: '35px', borderRadius: '50%', objectFit: 'cover' }, userInfo: { display: 'flex', gap: '15px', alignItems: 'center', color: 'white' },
  logoutButton: { backgroundColor: 'transparent', border: '1px solid white', color: 'white', padding: '6px 15px', borderRadius: '6px', cursor: 'pointer' },
  notificationDropdown: { position: 'absolute', top: '70px', right: '30px', width: '350px', borderRadius: '10px', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', zIndex: 1000, maxHeight: '400px', overflow: 'auto' },
  notificationHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '15px', borderBottom: '1px solid #e5e7eb' },
  markAllRead: { background: 'none', border: 'none', color: '#2563eb', cursor: 'pointer', fontSize: '12px' },
  notificationItem: { display: 'flex', gap: '12px', padding: '12px 15px', borderBottom: '1px solid #e5e7eb', cursor: 'pointer' },
  notificationIconSmall: { fontSize: '20px' }, notificationContent: { flex: 1 }, notificationTitle: { fontWeight: 'bold', marginBottom: '4px' },
